#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, datetime as dt, importlib.util, os, py_compile, re, shutil, subprocess, sys, tempfile
from pathlib import Path

VERSION="0.14.1"
MERGES_B64={'backend/app/services/vision_app/automation_manager.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/automation_models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/camera_resource_runtime.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/endpoint_registry.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/AutomationCodeEditor.tsx': {'old': '', 'new': ''}}
STREAMING_RUNTIME=base64.b64decode('').decode()
STREAM_UI=base64.b64decode('').decode()
TEST=base64.b64decode('').decode()
DOC=base64.b64decode('').decode()
API_BLOCK=base64.b64decode('').decode()
MERGES={k:{"old":base64.b64decode(v["old"]).decode(),"new":base64.b64decode(v["new"]).decode()} for k,v in MERGES_B64.items()}

def roots(f=None,b=None):
    c=Path.cwd().resolve(); fs=[]; bs=[]
    if f: fs.append(Path(f).expanduser().resolve())
    if b: bs.append(Path(b).expanduser().resolve())
    fs += [c,c/"LambdaVisionSuper",c.parent/"LambdaVisionSuper"]
    bs += [c,c/"LambdaVisionSuperBackEnd",c.parent/"LambdaVisionSuperBackEnd"]
    fe=next((p for p in fs if (p/"src/Pages/ComputerVisionPage.tsx").exists()),None)
    be=next((p for p in bs if (p/"app/services/vision_app/models.py").exists()),None)
    if not fe: raise RuntimeError("Cannot locate frontend")
    if not be: raise RuntimeError("Cannot locate backend")
    return fe,be

def rp(fe,be,v): return fe/v[9:] if v.startswith("frontend/") else be/v[8:]

def merge3(cur,old,new):
    if cur==new:return "OK",cur
    if cur==old:return "UPDATE",new
    with tempfile.TemporaryDirectory() as td:
        td=Path(td); a=td/"a"; o=td/"o"; n=td/"n"
        a.write_text(cur);o.write_text(old);n.write_text(new)
        p=subprocess.run(["git","merge-file","-p","--diff3",str(a),str(o),str(n)],text=True,capture_output=True)
        if p.returncode==0:return "MERGE",p.stdout
        return "CONFLICT",p.stdout

def post_merge(rel,text):
    if rel.endswith("automation_manager.py"):
        text=text.replace(
            "def _on_stream_status(self, program_id: str, camera_alias: str, stream: dict[str, Any], soft: dict[str, dict[str, Any]]) -> None:",
            "def _on_stream_status(self, program_id: str, workspace_alias: str, camera_alias: str, stream: dict[str, Any], soft: dict[str, Any]) -> None:"
        )
        text=text.replace("state.stream_states[camera_alias] = dict(stream)", "state.stream_states[workspace_alias] = dict(stream)")
        text=text.replace(
            "for alias, value in soft.items():\n            state.soft_trigger_states[alias] = dict(value)",
            "state.soft_trigger_states[workspace_alias] = dict(soft) if soft else {}"
        )
        text=text.replace(
            "camera = self._camera(program, camera_alias)\n            if workspace.soft_trigger.snapshot_to_image_slot:\n                VISION_FRAME_SLOTS.put(program_id, self.camera_resources.image_slot_path(camera), image)",
            "if workspace.soft_trigger.snapshot_to_image_slot:\n                self.set_latest_frame(program_id, image, workspace_alias=workspace_alias, announce=False)"
        )
        text=text.replace(
            "stream_state = self.state(program.program_id).stream_states.get(camera_alias, {})",
            "stream_state = self.state(program.program_id).stream_states.get(self.state(program.program_id).active_workspace, {})"
        )
        text=text.replace(
            "self.streaming.ensure(program.program_id, camera, f'ide:{alias}')",
            "self.streaming.ensure(program.program_id, self.state(program.program_id).active_workspace, camera, f'ide:{alias}')"
        )
        text=text.replace(
            "self.streaming.release(program.program_id, alias, f'ide:{alias}')",
            "self.streaming.release(program.program_id, self.state(program.program_id).active_workspace, f'ide:{alias}')"
        )
    elif rel.endswith("endpoint_registry.py"):
        text=text.replace(
            '(getattr(state, "stream_states", {}) or {}).get(alias, {}) if state is not None else {}',
            '(getattr(state, "stream_states", {}) or {}).get(getattr(state, "active_workspace", ""), {}) if state is not None else {}'
        )
    elif rel.endswith("visionAppApi.ts"):
        start=text.find("  streamStart:")
        end=text.find("  uploadSimCameraFrame:", start)
        if start!=-1 and end!=-1:
            block = """  streamStart: async (id:string,workspaceAlias:string):Promise<StreamingStatusResponse> => (await axiosClient.post(`${api_version}/computer-vision/programs/${encodeURIComponent(id)}/workspaces/${encodeURIComponent(workspaceAlias)}/stream/start`)).data,
  streamStop: async (id:string,workspaceAlias:string):Promise<StreamingStatusResponse> => (await axiosClient.delete(`${api_version}/computer-vision/programs/${encodeURIComponent(id)}/workspaces/${encodeURIComponent(workspaceAlias)}/stream/stop`)).data,
  streamStatus: async (id:string,workspaceAlias:string):Promise<StreamingStatusResponse> => (await axiosClient.get(`${api_version}/computer-vision/programs/${encodeURIComponent(id)}/workspaces/${encodeURIComponent(workspaceAlias)}/stream/status`)).data,
  streamLatestFrame: async (id:string,workspaceAlias:string,afterSequence=0):Promise<{blob:Blob|null;sequence:number}> => {
    const r=await axiosClient.get(`${api_version}/computer-vision/programs/${encodeURIComponent(id)}/workspaces/${encodeURIComponent(workspaceAlias)}/stream/frame`,{params:{after_sequence:afterSequence},responseType:'blob',validateStatus:(s:number)=>s===200||s===204});
    return {blob:r.status===204?null:r.data,sequence:Number(r.headers?.['x-frame-sequence']??afterSequence)};
  },
  analyzeSoftTrigger: async (id:string,workspaceAlias:string,config:SoftTriggerConfig):Promise<SoftTriggerAnalysis> => (await axiosClient.post(`${api_version}/computer-vision/programs/${encodeURIComponent(id)}/workspaces/${encodeURIComponent(workspaceAlias)}/soft-trigger/analyze`,config)).data,
"""
            text=text[:start]+block+text[end:]
        text=text.replace(
            "export interface StreamingStatusResponse { success:boolean; stream:CameraStreamStatus; soft_triggers:Record<string,SoftTriggerRuntimeStatus>; }",
            "export interface StreamingStatusResponse { success:boolean; stream:CameraStreamStatus; soft_trigger:SoftTriggerRuntimeStatus|null; }"
        )
    return text

def patch_api(text):
    if "SoftTriggerConfig" not in text[:2500]:
        text=text.replace(
            "from app.services.vision_app.models import VisionProgramDefinition, model_to_dict",
            "from app.services.vision_app.models import SoftTriggerConfig, VisionProgramDefinition, model_to_dict"
        )
    text=text.replace("automation_manager.stop(program_id)", "automation_manager.shutdown_program(program_id)")
    if "/workspaces/{workspace_alias}/stream/start" not in text:
        text += API_BLOCK
    return text

def patch_page(text):
    if "Activity" not in text.split("from 'lucide-react'")[0]:
        text=text.replace("import { ", "import { Activity, ", 1)
    if "StreamingWorkspace" not in text:
        text=text.replace(
            "import { CameraDeclarationWorkspace } from '../components/ComputerVision/CameraDeclarationWorkspace';",
            "import { CameraDeclarationWorkspace } from '../components/ComputerVision/CameraDeclarationWorkspace';\nimport { StreamingWorkspace } from '../components/ComputerVision/StreamingWorkspace';"
        )
    text=text.replace(
        "type ModuleKey='iot'|'camera'|'master'|'working'|'ide';",
        "type ModuleKey='iot'|'camera'|'streaming'|'master'|'working'|'ide';"
    )
    fresh_start=text.find("const freshWorkspace")
    page_start=text.find("export const ComputerVisionPage")
    if fresh_start!=-1 and page_start!=-1 and "soft_trigger:" not in text[fresh_start:page_start]:
        text=text.replace(
            "working:{global_scope:{enable_filter:true,filter_services:[],enable_logic:true,logic_services:[],enable_decision:false,decision:{script:''}},station_scopes:{},station_execution:'sequential',global_services:[],station_services:{}},",
            "working:{global_scope:{enable_filter:true,filter_services:[],enable_logic:true,logic_services:[],enable_decision:false,decision:{script:''}},station_scopes:{},station_execution:'sequential',global_services:[],station_services:{}},\n soft_trigger:{enabled:false,roi:null,threshold_mode:'bright',pixel_threshold:80,trigger_pixel_count:100,reset_pixel_count:20,frame_stride:1,cooldown_ms:500,snapshot_to_image_slot:true,run_inspection:true},"
        )
    if "const activeCamera=useMemo" not in text:
        marker="const enabledCameras=useMemo(()=>activeWorkspace?.cameras.devices.filter(c=>c.enabled)??[],[activeWorkspace?.workspace_id,activeWorkspace?.cameras.devices]);"
        if marker in text:
            text=text.replace(
                marker,
                marker+"\n const activeCamera=useMemo(()=>activeWorkspace?activeWorkspace.cameras.devices.find(c=>c.declaration_id===activeWorkspace.camera_id)??null:null,[activeWorkspace?.workspace_id,activeWorkspace?.cameras.devices,activeWorkspace?.camera_id]);"
            )
    if "key.NUM_" not in text:
        pattern=r"const keyName=\(e:KeyboardEvent\)=>\{.*?\n\s*\};"
        repl="""const keyName=(e:KeyboardEvent)=>{
     const c=e.code;
     if(/^Key[A-Z]$/.test(c))return `key.${c.slice(3)}`;
     if(/^Digit[0-9]$/.test(c))return `key.NUM_${c.slice(5)}`;
     if(/^Numpad[0-9]$/.test(c))return `key.NUMPAD_${c.slice(6)}`;
     const map:Record<string,string>={Space:'key.SPACE',Enter:'key.ENTER',Escape:'key.ESCAPE',Tab:'key.TAB',Backspace:'key.BACKSPACE',Delete:'key.DELETE',Insert:'key.INSERT',Home:'key.HOME',End:'key.END',PageUp:'key.PAGE_UP',PageDown:'key.PAGE_DOWN',ArrowUp:'key.ARROW_UP',ArrowDown:'key.ARROW_DOWN',ArrowLeft:'key.ARROW_LEFT',ArrowRight:'key.ARROW_RIGHT',ShiftLeft:'key.SHIFT',ShiftRight:'key.SHIFT',ControlLeft:'key.CTRL',ControlRight:'key.CTRL',AltLeft:'key.ALT',AltRight:'key.ALT',MetaLeft:'key.META',MetaRight:'key.META'};
     if(map[c])return map[c];
     if(/^F([1-9]|1[0-2])$/.test(c))return `key.${c}`;
     return null;
    };"""
        text=re.sub(pattern,repl,text,count=1,flags=re.S)
    text=text.replace(
        "{key:'camera',label:'Camera Declare',icon:Camera},{key:'master'",
        "{key:'camera',label:'Camera Declare',icon:Camera},{key:'streaming',label:'Streaming',icon:Activity},{key:'master'"
    )
    if "module==='streaming'?<StreamingWorkspace" not in text:
        needle="onScan={async()=>{const r=await VisionAppAPI.scanBasler();if(!r.success)setError(r.error||'Basler scan failed');return r.devices;}}/>:"
        if needle in text:
            text=text.replace(
                needle,
                needle[:-1]+":module==='streaming'?<StreamingWorkspace key={`streaming-${activeWorkspace.workspace_id}`} programId={program.program_id} workspace={activeWorkspace} camera={activeCamera} onWorkspace={next=>patchWorkspace(()=>next)} onError={setError}/>:",
                1
            )
    text=re.sub(r"Vision App v0\.13\.[0-9]+","Vision App v0.14.1",text)
    return text

def patch_context(text):
    text=text.replace(
        "Production Computer Vision application with v0.13.6 strict Workspace ownership: each Workspace owns IOT declarations, Camera declarations/binding, Master/ROI, Working scopes and run/debug context; typed dynamic Endpoint Registry and Automation IDE project only the active Workspace resources.",
        "Production Computer Vision application with v0.14.1 strict Workspace ownership: each Workspace owns IOT declarations, Camera declarations/binding, Master/ROI, Working scopes, Streaming/Soft Trigger and run/debug context; typed dynamic Endpoint Registry and Automation IDE project only the active Workspace resources."
    )
    text=text.replace(
        "Computer Vision is the production orchestration layer. v0.13.6 treats each Workspace as a fully independent inspection program: its own IOT declarations, Camera declarations/binding, Master image, ROI/locator definition, Working filter/logic scopes and debug/run context. New Workspaces start hardware-empty and no runtime resource may fall back to another Workspace.",
        "Computer Vision is the production orchestration layer. v0.14.1 keeps each Workspace fully independent: its own IOT declarations, Camera declarations/binding, Master/ROI, Working scopes and backend stream/Soft Trigger. Basler stream identity is workspace-scoped, browser preview is lazy, and no hardware/runtime resource may fall back to another Workspace."
    )
    if "# v0.14.1 Computer Vision:" not in text:
        text += "\n# v0.14.1 Computer Vision: workspace-owned Basler Streaming Service + lazy browser preview + per-workspace Soft Trigger + full keyboard.key namespace; HTTP/TCP streaming pending.\n"
    return text

def apply_model_post(text):
    text=text.replace(
        'stream_transport: Literal["native", "url", "tcp", "pending"] = "native"',
        'stream_transport: Literal["native", "url", "tcp", "pending"] = "pending"'
    )
    m=re.search(r"version: int = (\d+)",text)
    if m and int(m.group(1))<7:
        text=text[:m.start(1)]+"7"+text[m.end(1):]
    return text

def state_transform(fe,be,rel):
    p=rp(fe,be,rel)
    cur=p.read_text()
    if rel in MERGES:
        s,m=merge3(cur,MERGES[rel]["old"],MERGES[rel]["new"])
        if s=="CONFLICT":
            return "CONFLICT",None
        m=post_merge(rel,m)
        if rel.endswith("models.py") and not rel.endswith("automation_models.py"):
            m=apply_model_post(m)
        return ("OK" if m==cur else ("MERGE" if s=="MERGE" else "UPDATE")),m
    if rel=="backend/app/api/v1/endpoints/vision_app_api.py":
        new=patch_api(cur); return ("OK" if new==cur else "PATCH"),new
    if rel=="frontend/src/Pages/ComputerVisionPage.tsx":
        new=patch_page(cur); return ("OK" if new==cur else "PATCH"),new
    if rel=="frontend/tools/generate_llm_context_map.py":
        new=patch_context(cur); return ("OK" if new==cur else "PATCH"),new
    raise KeyError(rel)

TARGETS=list(MERGES)+[
    "backend/app/api/v1/endpoints/vision_app_api.py",
    "frontend/src/Pages/ComputerVisionPage.tsx",
    "frontend/tools/generate_llm_context_map.py",
]
CREATED={
    "backend/app/services/vision_app/streaming_runtime.py":STREAMING_RUNTIME,
    "backend/tests/vision_app/test_vision_app_v1410.py":TEST,
    "frontend/src/components/ComputerVision/StreamingWorkspace.tsx":STREAM_UI,
    "frontend/docs/llm_context/updates/v1410_workspace_owned_streaming.md":DOC,
}

def scan(fe,be):
    print("="*116)
    print("COMPUTER VISION V0.14.1 — WORKSPACE-OWNED STREAMING / SOFT TRIGGER")
    print("="*116)
    bad=0
    page=(fe/"src/Pages/ComputerVisionPage.tsx").read_text()
    if "activeWorkspace?.cameras.devices" not in page and "activeWorkspace.cameras.devices" not in page:
        print("[CONFLICT    ] v0.13.6 workspace-owned Camera architecture not detected")
        bad+=1
    for rel in TARGETS:
        try:s,_=state_transform(fe,be,rel)
        except Exception:s="ERROR"
        print(f"  [{s:12}] {rel}")
        if s in {"CONFLICT","ERROR"}:bad+=1
    for rel,content in CREATED.items():
        p=rp(fe,be,rel)
        s="CREATE" if not p.exists() else "OK" if p.read_text()==content else "CONFLICT"
        print(f"  [{s:12}] {rel}")
        if s=="CONFLICT":bad+=1
    print()
    print("PATCH/MERGE/UPDATE/CREATE are safe. CONFLICT/ERROR are blocking.")
    print("This release keeps IOT and Camera declarations inside each Workspace.")
    print("Stream identity is (program, workspace), so duplicate camera aliases across Workspaces do not share stream sessions.")
    if bad: print(f"[WARN] {bad} blocker(s). Do not apply.")
    else: print("[OK] Safe to apply.")
    return 1 if bad else 0

def regen(fe,be):
    g=fe/"tools/generate_llm_context_map.py"
    cmd=[sys.executable,str(g),"--frontend",str(fe),"--backend",str(be)]
    if "--output-dir" in g.read_text():
        cmd+=["--output-dir",str(fe/"docs/llm_context")]
    p=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
    if p.returncode:raise RuntimeError((p.stdout+"\n"+p.stderr).strip())
    if p.stdout.strip():print(p.stdout.strip())

def apply(fe,be):
    if scan(fe,be):raise RuntimeError("Preflight failed")
    stamp=dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    bak=fe/".lambda_updater_backups"/f"computer_vision_v1410_{stamp}"
    for rel in TARGETS+list(CREATED):
        p=rp(fe,be,rel)
        if p.exists():
            d=bak/rel;d.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,d)
    for rel in TARGETS:
        s,new=state_transform(fe,be,rel)
        if s!="OK":
            rp(fe,be,rel).write_text(new);print(f"[{s:6}] {rel}")
    for rel,c in CREATED.items():
        p=rp(fe,be,rel);p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists():
            p.write_text(c);print(f"[CREATE] {rel}")
    regen(fe,be)
    print("[OK] Backup:",bak)
    print("Run verify next.")
    return 0

def verify(fe,be,skip_build=False):
    print("="*116);print("VERIFY COMPUTER VISION V0.14.1");print("="*116)
    fail=0
    pyfiles=[
        be/"app/services/vision_app/streaming_runtime.py",
        be/"app/services/vision_app/automation_manager.py",
        be/"app/services/vision_app/endpoint_registry.py",
        be/"app/services/vision_app/models.py",
        be/"app/api/v1/endpoints/vision_app_api.py",
        be/"tests/vision_app/test_vision_app_v1410.py",
        fe/"tools/generate_llm_context_map.py",
    ]
    for p in pyfiles:
        try:py_compile.compile(str(p),doraise=True)
        except Exception as e:print("[FAIL] Python syntax",p,e);fail+=1
    if not fail:print("[OK] Python syntax")
    page=(fe/"src/Pages/ComputerVisionPage.tsx").read_text()
    api=(be/"app/api/v1/endpoints/vision_app_api.py").read_text()
    stream=(be/"app/services/vision_app/streaming_runtime.py").read_text()
    checks=[
        ("Workspace-owned camera UI preserved","activeWorkspace.cameras.devices" in page),
        ("Streaming module installed","StreamingWorkspace" in page and "label:'Streaming'" in page),
        ("Workspace-scoped stream API","/workspaces/{workspace_alias}/stream/start" in api),
        ("Workspace-scoped stream identity","workspace.cameras.devices" in stream),
        ("Soft Trigger runtime","class SoftTriggerRuntimeState" in stream and "trigger_pixel_count" in stream),
        ("Full keyboard endpoint","keyboard.key" in (be/"app/services/vision_app/endpoint_registry.py").read_text()),
        ("v0.14.1 handoff",(fe/"docs/llm_context/updates/v1410_workspace_owned_streaming.md").exists()),
    ]
    for label,ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        if not ok:fail+=1
    if importlib.util.find_spec("pytest") and (be/"tests/vision_app").exists():
        env=dict(os.environ);env["PYTHONPATH"]=str(be)+(os.pathsep+env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
        p=subprocess.run([sys.executable,"-m","pytest","-q","tests/vision_app"],cwd=str(be),env=env,text=True,capture_output=True)
        if p.returncode:
            print("[FAIL] pytest");print((p.stdout+p.stderr).strip());fail+=1
        else:
            print("[OK] Vision App regression tests");print(p.stdout.strip())
    if not skip_build and (fe/"node_modules").exists():
        p=subprocess.run(["npm","run","build"],cwd=str(fe))
        if p.returncode:print("[FAIL] Frontend npm build");fail+=1
        else:print("[OK] Frontend npm build")
    try:regen(fe,be);print("[OK] Context regeneration")
    except Exception as e:print("[FAIL] Context regeneration",e);fail+=1
    if fail:
        print(f"[FAIL] v0.14.1 verify: {fail} issue(s)")
        return 1
    print("[OK] Computer Vision v0.14.1 workspace-owned streaming verified.")
    return 0

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("command",choices=["scan","apply","verify"])
    ap.add_argument("--frontend");ap.add_argument("--backend");ap.add_argument("--skip-build",action="store_true")
    a=ap.parse_args()
    try:
        fe,be=roots(a.frontend,a.backend)
        return scan(fe,be) if a.command=="scan" else apply(fe,be) if a.command=="apply" else verify(fe,be,a.skip_build)
    except Exception as e:
        print("[ERROR]",e);return 2

if __name__=="__main__":
    raise SystemExit(main())
